 * @description ipt_companyName 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.ipt_companyName_onclick = function(e){
    try {
        scwin.clearBtnImage()

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldfil00037.ipt_companyName_onclick' }); }
};

/**
 * @method
 * @name btn_swapImage_onclick
 * @description 「ㄱ」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_swapImage_onclick = async function(e){
    try {
        scwin.swapImage($c.util.getComponent("btn_swapImage"), '01');await scwin.searchCorpListByBeginIndex()

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil00037.btn_swapImage_onclick' }); }
};

