/**
 * @method
 * @name __on_enter_2_ipt_companyname
 * @description on enter 2 ipt companyname 처리
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.__on_enter_2_ipt_companyname = async function(e){
    try {
        const ev = e;
        if(($c.util.getKeyCode(ev))===13){ await scwin.searchCorpList() }

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil00037.__on_enter_2_ipt_companyName' }); }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name tx_searchCorpList
 * @description search Corp List 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_searchCorpList = async function () {
    const sbmOptions = {
        id: "tx_searchCorpList",
        method: "post",
        action: "/submission/elwLpList.do?method=searchElwLp",
        ref: "dma_searchCorpListReq",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

/**
 * @method
 * @name tx_searchCorpListByBeginIndex
 * @description search Corp List By Begin Index 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_searchCorpListByBeginIndex = async function () {
    const sbmOptions = {
        id: "tx_searchCorpListByBeginIndex",
        method: "post",
        action: "/submission/elwLpList.do?method=searchElwLp",
        ref: "dma_searchCorpListByBeginIndexReq",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name searchCorpList
 * @description search Corp List 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.searchCorpList = async function () {
    scwin.clearBtnImage();
    $c.util.getComponent('dma_searchCorpListReq').set('beginIndex', "");
    (document.corpListForm || { elements: [] }).target = "iframe";
    await scwin.tx_searchCorpList();
};

/**
 * @method
 * @name searchCorpListByBeginIndex
 * @description search Corp List By Begin Index 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.searchCorpListByBeginIndex = async function () {
    await scwin.tx_searchCorpListByBeginIndex();
};

/**
 * @method
 * @name swapImage
 * @description swap Image 처리
 * @param {Object} obj 컴포넌트
 * @param {*} no no
 * @returns {void}
 * @hidden N
 */
scwin.swapImage = function (obj, no) {
    $c.util.getComponent('dma_searchCorpListReq').set('pageIndex', 1);
    scwin.clearBtnImage();
    $(obj).addClass("mga_5");
    if (no === "01") {
        $c.util.getComponent('dma_searchCorpListReq').set('beginIndex', "A");
    } else {
        if (no === "02") {
            $c.util.getComponent('dma_searchCorpListReq').set('beginIndex', "B");
        } else {
            if (no === "03") {
                $c.util.getComponent('dma_searchCorpListReq').set('beginIndex', "C");
            } else {
                if (no === "04") {
                    $c.util.getComponent('dma_searchCorpListReq').set('beginIndex', "D");
                } else {
                    if (no === "05") {
                        $c.util.getComponent('dma_searchCorpListReq').set('beginIndex', "E");
                    } else {
                        if (no === "06") {
                            $c.util.getComponent('dma_searchCorpListReq').set('beginIndex', "F");
                        } else {
                            if (no === "07") {
                                $c.util.getComponent('dma_searchCorpListReq').set('beginIndex', "G");
                            } else {
                                if (no === "08") {
                                    $c.util.getComponent('dma_searchCorpListReq').set('beginIndex', "H");
                                } else {
                                    if (no === "09") {
                                        $c.util.getComponent('dma_searchCorpListReq').set('beginIndex', "I");
                                    } else {
                                        if (no === "10") {
                                            $c.util.getComponent('dma_searchCorpListReq').set('beginIndex', "J");
                                        } else {
                                            if (no === "11") {
                                                $c.util.getComponent('dma_searchCorpListReq').set('beginIndex', "K");
                                            } else {
                                                if (no === "12") {
                                                    $c.util.getComponent('dma_searchCorpListReq').set('beginIndex', "L");
                                                } else {
                                                    if (no === "13") {
                                                        $c.util.getComponent('dma_searchCorpListReq').set('beginIndex', "M");
                                                    } else {
                                                        if (no === "14") {
                                                            $c.util.getComponent('dma_searchCorpListReq').set('beginIndex', "N");
                                                        } else {
                                                            if (no === "18") {
                                                                $c.util.getComponent('dma_searchCorpListReq').set('beginIndex', "AZ");
                                                            } else {
                                                                if (no === "17") {
                                                                    $c.util.getComponent('dma_searchCorpListReq').set('beginIndex', "ETC");
                                                                }
                                                            }
                                                        }
                                                    }
                                                }
                                            }
                                        }
                                    }
                                }
                            }
                        }
                    }
                }
            }
        }
    }
};

/**
 * @method
 * @name clearBtnImage
 * @description clear Btn Image 처리
 * @returns {void}
 * @hidden N
 */
scwin.clearBtnImage = function () {
    $("#phoneme").children("a").each(function() {
            $(this).removeClass("mga_5");
    });
};

/**
 * @method
 * @name setCorpInfo
 * @description set Corp Info 처리
 * @param {*} mktpartcNo mktpartcNo
 * @param {String} mktpartcKorNm mktpartcKorNm
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.setCorpInfo = async function (mktpartcNo, mktpartcKorNm) {
    try {
        (((scwin.openerScwin()) !== scwin && typeof (scwin.openerScwin()).setCorpInfo === 'function' ? (scwin.openerScwin()).setCorpInfo(mktpartcNo, mktpartcKorNm) : void 0), $c.win.closePopup([mktpartcNo, mktpartcKorNm]));
        $c.win.closePopup();
    } catch (e) { $c.exception.handleError(e, { notify: 'none', context: 'jldfil00037' });
        await $c.win.alert("<ERROR>\n\n" + "부모창을 찾을 수가 없습니다. \n\n" + "mktpartcNo : " + mktpartcNo + "\n" + "mktpartcKorNm : " + mktpartcKorNm + "\n");
    }
};

/**
 * @method
 * @name opener
 * @description 부모 화면 scope(browserPopup/pageFramePopup 공통 — $c.win.getOpenerScope). 단독 진입이거나 부모가 닫혀 없으면
 * @returns {Object} 부모 화면 scope 또는 빈 scope
 * @hidden N
 */
scwin.opener = function () {
    const scope = ($c.win && $c.win.getOpenerScope) ? $c.win.getOpenerScope() : null;
    return scope || { getComponentById: function () { return null; }, scwin: {} };
};

/**
 * @method
 * @name openerScwin
 * @description 부모 화면의 scwin(함수·전역 접근용). 부모가 없으면 빈 객체
 * @returns {Object} 부모 scwin 또는 {}
 * @hidden N
 */
scwin.openerScwin = function () {
    return scwin.opener().scwin || {};
};
